/* eslint-disable eqeqeq */
/* eslint-disable @typescript-eslint/naming-convention */
import { Component, OnInit, ViewChild } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { SafeUrl } from '@angular/platform-browser';
import { Router } from '@angular/router';
import { AlertController, IonContent, LoadingController, ToastController } from '@ionic/angular';
import { G } from 'src/app/core/common/G';
import { GResponse } from 'src/app/core/common/GResponse';
import { SharedIonic } from 'src/app/core/common/SharedIonic';
import { Urls } from 'src/app/core/common/Urls';
import { async } from '@angular/core/testing';
import { CourseService } from 'src/app/data/service/course/course.service';
import { SliderService } from 'src/app/data/service/site/Slider.service';
import { DatePipe } from '@angular/common';
import * as FileSaver from 'file-saver';

@Component({
  selector: 'app-afr',
  templateUrl: './afr.component.html',
  styleUrls: ['./afr.component.scss']
})
export class AFRComponent implements OnInit {

  @ViewChild(IonContent) content: IonContent;

  isShow = false;
  isCheck = true;
  queryText = '';
  showSearchbar = false;
  instagram: string | SafeUrl = '';
  twiter: string | SafeUrl = '';
  facebook: string | SafeUrl = '';
  telegram: string | SafeUrl = '';
  pinterest: string | SafeUrl = '';
  aparat: string | SafeUrl = '';
  discord: string | SafeUrl = '';
  youtube: string | SafeUrl = '';
  twitch: string | SafeUrl = '';
  linkedin: string | SafeUrl = '';
  form: FormGroup;

  AFR;
  minAFR;
  tableSize = 12;
  tableSizeSelected = '12';
  engineTypeSelected = '1';
  min = 300;
  max = 0;
  avg;
  date;
  stoich = 0;

  constructor(
    private fb: FormBuilder,
    private router: Router,
    public alertController: AlertController,
    public loadingController: LoadingController,
    public toastController: ToastController,
    private siteService: SliderService,
    private courseService: CourseService,
    private datePipe: DatePipe
  ) {
    this.isShow = false;
    SharedIonic.loading(this.loadingController);

    this.check();
  }

  tableSizeChanged() {

    this.tableSize = +this.tableSizeSelected;
  }

  async exportTable() {

    this.date = new Date();
    const latestDate = this.datePipe.transform(this.date, 'yyyy-MM-dd');
    const latestDateDetail = this.datePipe.transform(this.date, 'yyyy-MM-dd-h-mm-ss');

    let tableRpm = ``;
    let tableMap = ``;
    let tableContent = ``;

    for (let i = 1; i < this.AFR[0].length; i++) {
      const rpm = this.AFR[0][i];

      tableRpm += rpm + ` \n`;
    }

    for (let i = 1; i < this.AFR.length; i++) {
      const map1 = this.AFR[i];

      for (let j = 0; j < map1.length; j++) {
        const map = map1[j];

        // eslint-disable-next-line eqeqeq
        if (j == 0) {

          tableMap += map + ` \n`;
        } else {

          tableContent += map + ` `;
        }
      }
      tableContent += `\n`;
    }

    const content = `<?xml version="1.0" encoding="UTF-8" standalone="no"?>
    <tableData xmlns="http://localhost:4300/:table">
    <bibliography author="Nima Sedigh - avalamooz.ir.com" company="SuperTubo" writeDate="` + latestDate + `" />
    <versionInfo fileFormat="1.0"/>
    <table cols="` + this.form.value.x + `" rows="` + this.form.value.y + `">
    <xAxis cols="` + this.form.value.y + `" name="rpm">
             ` + tableRpm + `</xAxis>
    <yAxis name="afrload1" rows="` + this.form.value.y + `">
             ` + tableMap + `</yAxis>
    <zValues cols="` + this.form.value.x + `" rows="` + this.form.value.y + `">
             ` + tableContent + `</zValues>
    </table>
    </tableData>
    `;

    try {
      const blob = new Blob([content], { type: 'text/xml;charset=utf-8' });
      FileSaver.saveAs(blob, 'AFR Table - ' + latestDateDetail + '.table');
    } catch (e) {
      SharedIonic.toast(this.toastController, 'مرورگر شما از این قابلیت پشتیبانی نمیکند');
    }
  }

  async check() {

    SharedIonic.loading(this.loadingController);

    this.siteService.GetTunerPlusById(8).subscribe(
      res => {
        if (res.status === GResponse.SuccessStatus) {

          if (res.data.isActive) {

            if (!res.data.isFree) {

              this.courseService.GetUserCoursesId().subscribe(
                ress => {
                  if (ress.status === GResponse.SuccessStatus) {
                    let found = false;
                    res.data.courseIds.forEach(courseId => {

                      // eslint-disable-next-line eqeqeq
                      if (ress.data.find(n => n == courseId)) {
                        found = true;

                        this.courseService.GetUserTunerPlusAccess().subscribe(
                          resss => {
                            if (resss.status === GResponse.SuccessStatus) {

                              SharedIonic.dismissLoading(this.loadingController);
                              this.isCheck = false;

                            } else {
                              this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                              SharedIonic.dismissLoading(this.loadingController);
                            }
                          },
                          errs => {
                            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                            SharedIonic.dismissLoading(this.loadingController);
                          }
                        );
                      }
                    });

                    if (!found) {
                      this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                      SharedIonic.dismissLoading(this.loadingController);
                    }

                  } else {
                    this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                    SharedIonic.dismissLoading(this.loadingController);
                  }
                },
                errs => {
                  this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
                  SharedIonic.dismissLoading(this.loadingController);
                }
              );
            } else {
              SharedIonic.dismissLoading(this.loadingController);
              this.isCheck = false;
            }
          } else {
            this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
            SharedIonic.dismissLoading(this.loadingController);
          }
        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      err => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;

    this.form = this.fb.group({
      idleRpm: [900, [Validators.required, Validators.min(300), Validators.max(9000)]],
      rpmRedline: [7000, [Validators.required, Validators.min(3000), Validators.max(20000)]],
      peakHp: [100, [Validators.required, Validators.min(30), Validators.max(20000)]],
      peakHpRpm: [5000, [Validators.required, Validators.min(2000), Validators.max(20000)]],
      peakTorqu: [170, [Validators.required, Validators.min(20), Validators.max(20000)]],
      peakTorquRpm: [3000, [Validators.required, Validators.min(1000), Validators.max(20000)]],
      engineVolum: [2000, [Validators.required, Validators.min(600), Validators.max(20000)]],
      boost: [0, [Validators.required, Validators.min(0), Validators.max(200)]],
      x: [16, [Validators.required, Validators.min(4), Validators.max(50)]],
      y: [16, [Validators.required, Validators.min(4), Validators.max(50)]],
      sto: [14.7, [Validators.required, Validators.min(0), Validators.max(60)]],
    });
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  onCalc() {

    if (!this.form.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.courseService.GetUserTunerPlusAccess().subscribe(
      resss => {
        if (resss.status === GResponse.SuccessStatus) {

          if (!this.check_errors()) {

            SharedIonic.dismissLoading(this.loadingController);
          } else {

            this.stoich = 100 - +this.form.value.sto * 100 / 14.7;
            this.make_AFR_table(this.tableSize);
            this.rpm_bins(this.form.value.rpmRedline, this.form.value.idleRpm);
            this.map_bins(this.form.value.boost);
            this.compute_AFRs();
            this.calcMinMax();

            this.isShow = true;
            SharedIonic.dismissLoading(this.loadingController);
          }

        } else {
          this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
          SharedIonic.dismissLoading(this.loadingController);
        }
      },
      errs => {
        this.router.navigateByUrl(Urls.AccessDeniedTunerPlusUrl);
        SharedIonic.dismissLoading(this.loadingController);
      }
    );
  }

  async calcMinMax() {

    this.min = 300;
    this.max = 0;

    for (let i = 1; i < this.AFR.length; i++) {

      // tslint:disable-next-line: prefer-for-of
      for (let j = 1; j < this.AFR[i].length; j++) {

        const ve = this.AFR[i][j];

        if (ve < this.min) {
          this.min = ve;
        }
        if (ve > this.max) {
          this.max = ve;
        }
      }
    }

    this.avg = (((this.max - this.min) / 2) + this.min);
  }

  calcColor(ve, j): string {

    let r = 135;
    let g = 135;
    let b = 135;

    if (j == 0) {
      return 'black';
    } else {

      if (ve >= this.avg) {

        r = ((((ve - this.min) * 100) / (this.max - this.min)) * 255) / 100;
        r += 3;
        g = ((100 - ((ve - this.avg) * 100) / (this.max - this.avg)) * 255) / 100;
        g += 34;

        if (g < 135) {
          g = 135;
        }
        if (g > 255) {
          g = 255;
        }
        if (r < 135) {
          r = 135;
        }
        if (r > 255) {
          r = 255;
        }
      } else {

        b = ((100 - (((ve - this.min) * 100) / (this.max - this.min))) * 255) / 100;
        b += 3;
        g = ((((ve - this.min) * 100) / (this.avg - this.min)) * 255) / 100;
        g += 34;

        if (g < 135) {
          g = 135;
        }
        if (g > 255) {
          g = 255;
        }
        if (b < 135) {
          b = 135;
        }
        if (b > 255) {
          b = 255;
        }
      }
      return 'rgb(' + r.toString() + ', ' + g.toString() + ', ' + b.toString() + ')';
    }
  }

  async make_AFR_table(size) {
    // Create AFR Array
    // AFR[i][j] is the volumetric efficiency(VE) * gamma  value
    // for the ith MAP bin, jth RPM bin (i,j=1..8)
    // where gamma=14.7/afr for gasoline.
    // AFR[i][0] is the ith MAP bin value (i=1..8)
    // AFR[0][j] is the jth RPM bin value (j=1..8)
    // AFR[0][0] is the kPa row with the value nearest 100kPa (i.e. the 'normally aspirated' row)
    //          and is it determined in function 'map_bins' - set but not used in this code version
    this.AFR = new Array(this.form.value.x + 1);
    for (let i = 0; i <= this.form.value.x; i++) {
      this.AFR[i] = new Array(this.form.value.y + 1);
    }
    // Initialize AFR Array
    // tslint:disable-next-line: forin
    for (const j in this.AFR) {
      for (let k = 0; k <= this.form.value.y; k++) {
        this.AFR[j][k] = 0;
      }
    }
    return;
  }

  async rpm_bins(maxrpm, idlerpm) {
    // Calculate RPM bins
    this.AFR[0][1] = Math.round((parseFloat(idlerpm) - 150) / 100) * 100;
    this.AFR[0][2] = Math.round((parseFloat(idlerpm) + 350) / 100) * 100;
    const rpm_bin_step = (parseFloat(maxrpm) - this.AFR[0][2]) / (this.form.value.y * 1.0 - 2);
    for (let i = 3; i <= (this.form.value.y * 1.0 - 1); i++) {
      this.AFR[0][i] = Math.round((this.AFR[0][2] + (i - 2) * rpm_bin_step) / 100) * 100;
    }
    this.AFR[0][(this.form.value.y * 1.0)] = Math.round(parseFloat(maxrpm) / 100) * 100;
    return;
  }


  async map_bins(maxmap) {
    // Calculate MAP bins
    // First bin is 25 kPa. Rest are evenly spaced to 'boost' value (maxmap).
    this.AFR[1][0] = 25; // Always start at 25 kPa
    const map_bin_step = (((parseFloat(maxmap) * (101.3 / 14.7) + 101.3) - this.AFR[1][0])) / (this.form.value.x * 1.0 - 1);
    for (let i = 2; i <= ((this.form.value.x * 1.0) - 1); i++) {
      this.AFR[i][0] = Math.round((this.AFR[1][0] + (i - 1) * map_bin_step) / 2) * 2;
      if (this.AFR[i][0] < 115) {
        this.AFR[0][0] = i;
      }
      this.AFR[(this.form.value.x * 1.0)][0] = Math.round(parseFloat(maxmap) * (101.3 / 14.7) + 101.3);
    }
    return;
  }

  async compute_AFRs() {

    // Get form values
    const peak_tq = (this.form.value.peakTorqu / 1.3558179999442195);
    const peak_hp = this.form.value.peakHp;
    const maxmap = this.form.value.boost;
    const displacement = ((this.form.value.engineVolum / 1000) * 61); // swept volume in cubic inches
    const peak_hp_rpm = this.form.value.peakHpRpm;
    const peak_torque_rpm = this.form.value.peakTorquRpm;

    // Compute torque at peak horsepower and torque - adjusted for any boost
    let compressor_efficiency = 1;
    if (maxmap > 0) { compressor_efficiency = 0.6; }
    const na_tq = peak_tq * (14.7 / (14.7 + (maxmap * compressor_efficiency)));
    const na_hp = peak_hp * (14.7 / (14.7 + (maxmap * compressor_efficiency))) * (5250 / peak_hp_rpm);

    // Compute specific output ranges
    if (((na_hp / displacement) > 1.2) || (maxmap > 8)) {
      // high output
      this.minAFR = 1200; // target AFR x100
    }
    else if ((na_hp / displacement) > 0.7) {
      // medium output
      this.minAFR = 1250;
    }
    else {
      // low output
      this.minAFR = 1300;
    }
    // Set K - the 'step' degradation ration for AFR to kPa
    const K = -0.02; // for every 100 kPa, lower the AFR by 2.0:1

    // Fill the AFR values
    // (but not the bin values)

    if (this.engineTypeSelected === '1') {

      for (let i = 1; i <= (this.form.value.x * 1.0); i++) {
        for (let j = 1; j <= (this.form.value.y * 1.0); j++) {
          compressor_efficiency = 1;
          if (this.AFR[i][0] > 100) { compressor_efficiency = 0.6; }
          const f = (100 - (100 - this.AFR[i][0]) * K) / 100;
          if (j <= 2) {
            this.AFR[i][j] = (this.minAFR + 80) / 100;
          }
          else { // not idling
            if (this.AFR[0][j] < peak_torque_rpm) {
              this.AFR[i][j] = (this.minAFR + 60);
            }
            else if (this.AFR[0][j] > peak_hp_rpm) {
              this.AFR[i][j] = this.minAFR;
            }
            else {
              this.AFR[i][j] = this.minAFR + 60 / (peak_hp_rpm - peak_torque_rpm) * (peak_hp_rpm - this.AFR[0][j]);
            }
            // adjust for MAP
            this.AFR[i][j] = (this.AFR[i][j] / 100) - (100 - this.AFR[i][0]) * K;
          }
          this.AFR[i][j] = Math.round((this.AFR[i][j] - this.AFR[i][j] * this.stoich / 100) * 10) / 10;
        }
      }
    } else if (this.engineTypeSelected === '2') {
      for (let i = 1; i <= (this.form.value.x * 1.0); i++) {
        for (let j = 1; j <= (this.form.value.y * 1.0); j++) {
          compressor_efficiency = 1;
          if (this.AFR[i][0] > 100) { compressor_efficiency = 0.6; }
          const f = (100 - (100 - this.AFR[i][0]) * K) / 100;
          if (j <= 2) {
            this.AFR[i][j] = (this.minAFR + 80) / 100;
          }
          else { // not idling
            if (this.AFR[0][j] < peak_torque_rpm) {
              this.AFR[i][j] = (this.minAFR + 60);
            }
            else if (this.AFR[0][j] > peak_hp_rpm) {
              this.AFR[i][j] = this.minAFR;
            }
            else {
              this.AFR[i][j] = this.minAFR + 60 / (peak_hp_rpm - peak_torque_rpm) * (peak_hp_rpm - this.AFR[0][j]);
            }
            // adjust for MAP
            this.AFR[i][j] = (this.AFR[i][j] / 100) - (100 - this.AFR[i][0]) * K;
          }
          this.AFR[i][j] = (Math.round((this.AFR[i][j] - this.AFR[i][j] * this.stoich / 100) * 10) / 10) - 1;
        }
      }
    }
  }

  async check_errors() {
    // check for
    // idle_rpm > 300
    // max_rpm < 12000
    // boost < 21psi
    // 25 < idle_map > 4
    // phprpm > phprpm
    // peak_tq > peak_hp*5250/phprpm
    // peak_hp/displacement < 3.0 hp/ci
    // errors is a string with all error messages
    const err_idle_rpm = this.form.value.idleRpm;
    const err_maxrpm = this.form.value.rpmRedline;
    const err_peak_tq = (this.form.value.peakTorqu / 1.3558179999442195);
    const err_tq_rpm = this.form.value.peakTorquRpm;
    const err_boost = this.form.value.boost;
    const err_peak_hp = this.form.value.peakHp;
    const err_hp_rpm = this.form.value.peakHpRpm;
    const err_displacement = ((this.form.value.engineVolum / 1000) * 61); // swept volume in cubic inches
    let errors = '';
    if (err_idle_rpm < 300) {
      errors = 'Idle rpm set too low. ';
      SharedIonic.toast(this.toastController, 'دور آرام نباید کمتر از 300 باشد');
    }
    else if (err_maxrpm > 20000) {
      errors = errors + 'Maximum RPM is set too high. ';
      SharedIonic.toast(this.toastController, 'دور موتور کاتاف نباید بیشتر از 20000 باشد');
    }
    else if (err_boost > 200) {
      errors = errors + 'Maximum boost is set too high for standard MegaSquirt<sup>&reg;</sup> MPX4250 MAP sensor. ';
      SharedIonic.toast(this.toastController, 'بوست توربو نباید بیشتر از 200 باشد');
    }
    else if (err_tq_rpm > err_hp_rpm) {
      errors = errors + 'RPM for peak torque occurs above RPM for peak horsepower. ';
      SharedIonic.toast(this.toastController, 'دور موتور اوج گشتاور نباید بیشتر از توان باشد');
    }
    else if ((err_peak_hp * 5252 / err_hp_rpm) > err_peak_tq) {
      errors = errors + 'Torque at maximum HP is higher than at \'peak\' torque! ';
      SharedIonic.toast(this.toastController, 'گشتاور در اوج توان نباید بیشتر از اوج گشتاور باشد');
    }
    else if ((err_peak_hp / err_displacement) > 3) {
      errors = errors + 'Specific output is too high to model. ';
      SharedIonic.toast(this.toastController, 'خروجی خاص برای مدل سازی خیلی زیاد است');
    }
    else if (errors === '') {
      return false;
    }
    else {
      return true;
    }
  }

  onBack() {

    this.isShow = false;
  }

  onInfo(type: string) {

    switch (type) {
      case 'idleRpm':
        this.presentActiveAlertConfirm('دور موتور در زمانی که پدال گاز رها است را وارد کنید. معمولا عددی بین 700 الی 1300');
        break;
      case 'rpmRedline':
        this.presentActiveAlertConfirm('بیشترین دور موتور تعیین شده برای خودرو که در محدوده قرمز صفحه کیلومتر نشان داده میشود');
        break;
      case 'peakHp':
        this.presentActiveAlertConfirm('بیشینه ی توان موتور در سر فلایول برحسب اسب بخار');
        break;
      case 'peakHpRpm':
        this.presentActiveAlertConfirm('دور موتوری که بیشینه ی توان موتور در آن بدست آمده است');
        break;
      case 'peakTorqu':
        this.presentActiveAlertConfirm('بیشینه ی گشتاور موتور در سر فلایول برحسب نیوتن متر');
        break;
      case 'peakTorquRpm':
        this.presentActiveAlertConfirm('دور موتوری که بیشینه ی گشتاور موتور در آن بدست آمده است');
        break;
      case 'engineVolum':
        this.presentActiveAlertConfirm('حجم موتور بر حسب سی سی');
        break;
      case 'boost':
        this.presentActiveAlertConfirm('اگر خودرو تنفس طبیعی است و توربو یا سوپرشارژ ندارد،مقدار صفر وارد شود. در غیر این صورت بیشترین فشار هوایی که توربو یا سوپرشارژ به موتور اعمال میکند وارد شود بر حسب پی اس آی');
        break;
      case 'x':
        this.presentActiveAlertConfirm('تعداد سطر های جدول یا همان x جدول میباشد');
        break;
      case 'y':
        this.presentActiveAlertConfirm('تعداد ستون های جدول یا همان y جدول میباشد');
        break;
      case 'sto':
        this.presentActiveAlertConfirm('ضریب استوکیومتری سوخت مصرفی. برای بنزین معمولی 14.7');
        break;

      default:
        break;
    }
  }

  async presentActiveAlertConfirm(msg: string = '') {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'توضیحات',
      message: msg,
      buttons: [
        {
          text: 'بستن',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }
      ]
    });

    await alert.present();
  }
}
